1: #!/usr/bin/env node
2: // Replay persona probes against an isolated agent and dump raw replies.
3: // Never point this at the live agent on 3710: every probe archives the active
4: // thread, which would cut Doc's real conversation in half.
5: import { mkdirSync, writeFileSync } from "node:fs";
6: import { join } from "node:path";
7: import { OUT_ROOT, envValue, loadProbes, stamp } from "./lib.mjs";
8: 
9: function parseArgs(argv) {
10:   const args = { url: "http://127.0.0.1:3712", label: "", tags: "", seeds: 1 };
11:   for (let i = 0; i < argv.length; i++) {
12:     const a = argv[i];
13:     if (a === "--url") args.url = argv[++i] ?? args.url;
14:     else if (a === "--label") args.label = argv[++i] ?? "";
15:     else if (a === "--tags") args.tags = argv[++i] ?? "";
16:     else if (a === "--seeds") args.seeds = Number(argv[++i] ?? 1);
17:   }
18:   return args;
19: }
20: 
21: async function post(url, body) {
22:   const res = await fetch(url, {
23:     method: "POST",
24:     headers: { "Content-Type": "application/json" },
25:     body: JSON.stringify(body),
26:   });
27:   const text = await res.text();
28:   let json;
29:   try {
30:     json = JSON.parse(text);
31:   } catch {
32:     json = { raw: text };
33:   }
34:   if (!res.ok) {
35:     const detail = json?.error?.message ?? json?.message ?? text.slice(0, 200);
36:     throw new Error(`${res.status} ${url}: ${detail}`);
37:   }
38:   return json;
39: }
40: 
41: async function waitForAgent(url, timeoutMs = 60000) {
42:   const deadline = Date.now() + timeoutMs;
43:   let last = "";
44:   while (Date.now() < deadline) {
45:     try {
46:       const res = await fetch(`${url}/health`);
47:       const health = await res.json();
48:       if (health.ready) return health;
49:       last = `state=${health.state}`;
50:     } catch (err) {
51:       last = err instanceof Error ? err.message : String(err);
52:     }
53:     await new Promise((r) => setTimeout(r, 1000));
54:   }
55:   throw new Error(`agent at ${url} never became ready (${last})`);
56: }
57: 
58: async function main() {
59:   const args = parseArgs(process.argv.slice(2));
60:   if (/:3710(\/|$)/.test(args.url)) {
61:     console.error(
62:       "refusing to run against port 3710: probes archive threads and would truncate the live conversation",
63:     );
64:     process.exit(2);
65:   }
66: 
67:   const ownerId = envValue("MEMORY_OWNER_ID", "DISCORD_OWNER_ID");
68:   if (!ownerId) {
69:     console.error("MEMORY_OWNER_ID / DISCORD_OWNER_ID not found in env");
70:     process.exit(2);
71:   }
72: 
73:   const all = loadProbes();
74:   const wanted = args.tags
75:     .split(",")
76:     .map((t) => t.trim())
77:     .filter(Boolean);
78:   const probes = wanted.length
79:     ? all.filter((p) => p.tags.some((t) => wanted.includes(t)))
80:     : all;
81: 
82:   if (probes.length === 0) {
83:     console.error(`no probes matched tags: ${args.tags}`);
84:     process.exit(2);
85:   }
86: 
87:   const health = await waitForAgent(args.url);
88:   const label = args.label || `run-${stamp()}`;
89:   const outDir = join(OUT_ROOT, label);
90:   mkdirSync(outDir, { recursive: true });
91: 
92:   console.log(
93:     `[replay] ${probes.length} probes x ${args.seeds} on ${args.url} (${health.mistral?.model})`,
94:   );
95: 
96:   const results = [];
97:   for (const probe of probes) {
98:     for (let seed = 1; seed <= args.seeds; seed++) {
99:       // Fresh thread per run so probes cannot contaminate each other.
100:       await post(`${args.url}/memory/newthread`, { userId: ownerId });
101:       const turns = [];
102:       let failed = null;
103:       for (const message of probe.turns) {
104:         const startedAt = Date.now();
105:         try {
106:           const reply = await post(`${args.url}/chat/text`, {
107:             message,
108:             channel: "discord",
109:             userId: ownerId,
110:           });
111:           turns.push({
112:             user: message,
113:             reply: reply.text ?? "",
114:             latencyMs: Date.now() - startedAt,
115:           });
116:         } catch (err) {
117:           failed = err instanceof Error ? err.message : String(err);
118:           turns.push({ user: message, reply: "", latencyMs: Date.now() - startedAt });
119:           break;
120:         }
121:       }
122:       results.push({
123:         id: probe.id,
124:         tags: probe.tags,
125:         lang: probe.lang,
126:         // Carried through so the judge sees the pass condition, not just the text.
127:         note: probe.note ?? "",
128:         seed,
129:         turns,
130:         error: failed,
131:       });
132:       const marker = failed ? "FAIL" : "ok";
133:       console.log(`  ${marker} ${probe.id}${args.seeds > 1 ? ` seed${seed}` : ""}`);
134:       if (failed) console.log(`     ${failed}`);
135:     }
136:   }
137: 
138:   const run = {
139:     label,
140:     at: new Date().toISOString(),
141:     url: args.url,
142:     model: health.mistral?.model ?? null,
143:     seeds: args.seeds,
144:     probeCount: probes.length,
145:     results,
146:   };
147:   writeFileSync(join(outDir, "run.json"), JSON.stringify(run, null, 2), "utf-8");
148: 
149:   const md = [`# ${label}`, "", `Model: ${run.model}  ${run.at}`, ""];
150:   for (const r of results) {
151:     md.push(`## ${r.id}${args.seeds > 1 ? ` (seed ${r.seed})` : ""}`);
152:     md.push(`tags: ${r.tags.join(", ")} | lang: ${r.lang}`, "");
153:     for (const t of r.turns) {
154:       md.push(`**Doc:** ${t.user}`, "");
155:       md.push(`**Ashley** (${t.latencyMs}ms):`, "");
156:       md.push(t.reply ? t.reply.split("\n").map((l) => `> ${l}`).join("\n") : "> (no reply)");
157:       md.push("");
158:     }
159:     if (r.error) md.push(`ERROR: ${r.error}`, "");
160:   }
161:   writeFileSync(join(outDir, "replies.md"), md.join("\n"), "utf-8");
162: 
163:   const failures = results.filter((r) => r.error).length;
164:   console.log(`[replay] wrote ${outDir}`);
165:   if (failures) {
166:     console.log(`[replay] ${failures} probe(s) errored`);
167:     process.exit(1);
168:   }
169: }
170: 
171: main().catch((err) => {
172:   console.error(err instanceof Error ? err.message : err);
173:   process.exit(1);
174: });
